if (root == nullptr) return;

if (item < root->value) {
    avlDelete(root->left, item);
} else if (item > root->value) {
    avlDelete(root->right, item);
} else {
    if (root->left == nullptr || root->right == nullptr) {
        TreeNode<int>* temp = root->left ? root->left : root->right;
        if (temp == nullptr) {
            temp = root;
            root = nullptr;
        } else {
            *root = *temp;
        }
        delete temp;
    } else {
        TreeNode<int>* temp = root->right;
        while (temp->left != nullptr) {
            temp = temp->left;
        }
        root->value = temp->value;
        avlDelete(root->right, temp->value);
    }
}

if (root == nullptr) return;

avlUpdateHeight(root);
int balance = avlGetBalance(root);

if (balance > 1 && avlGetBalance(root->left) >= 0) {
    avlRotateRight(root);
} else if (balance > 1 && avlGetBalance(root->left) < 0) {
    avlRotateLeft(root->left);
    avlRotateRight(root);
} else if (balance < -1 && avlGetBalance(root->right) <= 0) {
    avlRotateLeft(root);
} else if (balance < -1 && avlGetBalance(root->right) > 0) {
    avlRotateRight(root->right);
    avlRotateLeft(root);
}

